function tokenFor(user) { return jwt.sign({ id: String(user.id), role: user.role }, JWT_SECRET, { expiresIn: '12h', issuer: 'darbak' }); }
async function auth(req, res, next) {
  const h = req.headers.authorization || '';
  const token = h.startsWith('Bearer ') ? h.slice(7) : req.cookies.darbak_token;
  if (!token) return res.status(401).json({ error: 'يرجى تسجيل الدخول أولًا.' });
  try { req.auth = jwt.verify(token, JWT_SECRET, { issuer: 'darbak' }); const u=await query('SELECT must_change_password FROM users WHERE id=$1',[req.auth.id]); if(u.rows[0]?.must_change_password && !['/api/me','/api/auth/change-password'].includes(req.path)) return res.status(403).json({error:'يجب تغيير كلمة المرور المؤقتة قبل استخدام بقية النظام.'}); next(); }
  catch (e) { if(e?.name==='JsonWebTokenError'||e?.name==='TokenExpiredError') return res.status(401).json({ error: 'انتهت الجلسة أو أن رمز الدخول غير صالح.' }); next(e); }
}
const roles = (...allowed) => (req,res,next) => { if (!req.auth || !allowed.includes(req.auth.role)) return res.status(403).json({error:'ليست لديك صلاحية لتنفيذ هذا الإجراء.'}); next(); };
const superAdminOnly = async (req,res,next) => { try { const r=await query("SELECT is_super_admin FROM users WHERE id=$1 AND role='admin'",[req.auth.id]); if(!r.rows[0]?.is_super_admin)return res.status(403).json({error:'هذا الإجراء مخصص للمدير العام فقط.'}); next(); } catch(e){ next(e); } };
async function audit(req, action, entityType='', entityId='', details={}) {
  try { await query('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,ip,details) VALUES($1,$2,$3,$4,$5,$6)', [req.auth?.id || null, action, entityType, String(entityId||''), req.ip || '', JSON.stringify(details)]); } catch(e) { console.error('audit:', e.message); }
}
async function event(orderId, actorId, type, fromStatus=null, toStatus=null, note='', metadata={}) {
  await query('INSERT INTO order_events(order_id,actor_id,event_type,from_status,to_status,note,metadata) VALUES($1,$2,$3,$4,$5,$6,$7)', [orderId, actorId || null, type, fromStatus, toStatus, note, JSON.stringify(metadata)]);
}
function cleanUser(row) { if (!row) return row; const {password_hash, ...safe} = row; return safe; }

