// Authentication and registration
const otpStore = new Map();
app.post('/api/auth/request-otp', async (req,res) => {
  const phone = String(req.body.phone||'').trim();
  if (!/^\+?[0-9\s()-]{7,20}$/.test(phone)) return res.status(400).json({error:'أدخل رقم هاتف صحيحًا مع مفتاح الدولة عند الحاجة.'});
  const code = String(crypto.randomInt(100000,999999));
  otpStore.set(phone, {code, expires:Date.now()+Number(process.env.OTP_TTL_SECONDS||300)*1000});
  if (process.env.NODE_ENV !== 'production' && process.env.OTP_MODE === 'console') { console.log(`[DEV OTP] ${phone}: ${code}`); }
  else if (process.env.TWILIO_ACCOUNT_SID && process.env.TWILIO_AUTH_TOKEN && process.env.TWILIO_FROM_NUMBER) {
    const form = new URLSearchParams({To:phone,From:process.env.TWILIO_FROM_NUMBER,Body:`رمز التحقق لتطبيق البنشر الذكي هو ${code}. صالح لمدة ${Math.ceil(Number(process.env.OTP_TTL_SECONDS||300)/60)} دقائق.`});
    const twilio = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${process.env.TWILIO_ACCOUNT_SID}/Messages.json`, {method:'POST',headers:{Authorization:'Basic '+Buffer.from(`${process.env.TWILIO_ACCOUNT_SID}:${process.env.TWILIO_AUTH_TOKEN}`).toString('base64'),'Content-Type':'application/x-www-form-urlencoded'},body:form});
    if (!twilio.ok) { otpStore.delete(phone); console.error('Twilio SMS failed:', await twilio.text()); return res.status(502).json({error:'تعذر إرسال رمز التحقق. تحقق من إعدادات خدمة الرسائل.'}); }
  } else { otpStore.delete(phone); return res.status(503).json({error:'خدمة إرسال رمز التحقق غير مهيأة. أضف TWILIO_ACCOUNT_SID وTWILIO_AUTH_TOKEN وTWILIO_FROM_NUMBER، أو استخدم وضع التطوير محليًا.'}); }
  res.json({ok:true,message:process.env.NODE_ENV==='production'?'تم إرسال رمز التحقق إلى هاتفك.':'تم إنشاء رمز التحقق. في وضع التطوير يظهر الرمز في سجل تشغيل الخادم.', ...(process.env.NODE_ENV!=='production'?{devOnly:true}:{})});
});
app.post('/api/auth/verify-otp', async (req,res) => {
  const phone=String(req.body.phone||'').trim(), code=String(req.body.code||'').trim(), entry=otpStore.get(phone);
  if (!entry || entry.expires<Date.now() || entry.code!==code) return res.status(400).json({error:'رمز التحقق غير صحيح أو انتهت صلاحيته.'});
  otpStore.delete(phone);
  let r=await query("SELECT * FROM users WHERE phone=$1 AND role='customer'",[phone]);
  let user=r.rows[0];
  if (!user) { r=await query("INSERT INTO users(role,name,phone,status,phone_verified) VALUES('customer',$1,$2,'active',true) RETURNING *",['عميل',phone]); user=r.rows[0]; }
  else await query('UPDATE users SET phone_verified=true,updated_at=NOW() WHERE id=$1',[user.id]);
  res.json({token:tokenFor(user),user:cleanUser(user)});
});
app.post('/api/auth/provider-register', async (req,res) => {
  const {name,phone,email,password,businessName,vehicleType,vehiclePlate,vehicleDescription}=req.body;
  if (!name || !phone || !password || String(password).length<10) return res.status(400).json({error:'الاسم والهاتف وكلمة مرور لا تقل عن 10 أحرف مطلوبة.'});
  const hash=await bcrypt.hash(String(password),12);
  try {
    const r=await query("INSERT INTO users(role,name,phone,email,password_hash,status) VALUES('provider',$1,$2,$3,$4,'pending') RETURNING id,name,phone,email,role,status",[String(name).trim(),String(phone).trim(),email?String(email).trim().toLowerCase():null,hash]);
    await query('INSERT INTO provider_profiles(user_id,business_name,vehicle_type,vehicle_plate,vehicle_description,availability) VALUES($1,$2,$3,$4,$5,\'offline\')',[r.rows[0].id,businessName||'',vehicleType||'',vehiclePlate||'',vehicleDescription||'']);
    await audit({auth:{id:r.rows[0].id},ip:req.ip},'provider_registration','provider',r.rows[0].id);
    res.status(201).json({ok:true,message:'تم إنشاء الطلب. ارفع وثائقك ثم انتظر اعتماد الإدارة.',user:r.rows[0]});
  } catch(e) { if(e.code==='23505') return res.status(409).json({error:'رقم الهاتف أو البريد الإلكتروني مسجل مسبقًا.'}); throw e; }
});
app.post('/api/auth/login', async (req,res) => {
  const {identifier,password,role}=req.body;
  if (!identifier||!password) return res.status(400).json({error:'أدخل بيانات الدخول.'});
  const id=String(identifier).trim();
  const r=await query('SELECT * FROM users WHERE (LOWER(COALESCE(email,\'\'))=LOWER($1) OR phone=$1) AND role=$2',[id, role]);
  let user=r.rows[0];
  if (!user || !user.password_hash || !(await bcrypt.compare(String(password),user.password_hash))) return res.status(401).json({error:'بيانات الدخول غير صحيحة.'});
  if (user.status==='suspended') return res.status(403).json({error:'الحساب موقوف. تواصل مع الإدارة.'});
  if (user.role!==role) return res.status(403).json({error:'هذا الحساب لا يملك صلاحية الدخول إلى هذه الواجهة.'});
  res.json({token:tokenFor(user),user:cleanUser(user)});
});
app.get('/api/me',auth,async(req,res)=>{const r=await query('SELECT * FROM users WHERE id=$1',[req.auth.id]);if(!r.rows[0])return res.status(404).json({error:'الحساب غير موجود.'});const u=cleanUser(r.rows[0]);if(u.role==='provider'){const p=await query('SELECT * FROM provider_profiles WHERE user_id=$1',[u.id]);u.providerProfile=p.rows[0]||null;}res.json({user:u});});
app.post('/api/auth/change-password',auth,async(req,res)=>{const old=String(req.body.oldPassword||''), next=String(req.body.newPassword||'');if(next.length<12)return res.status(400).json({error:'كلمة المرور الجديدة يجب أن تكون 12 حرفًا على الأقل.'});const r=await query('SELECT password_hash FROM users WHERE id=$1',[req.auth.id]);if(!r.rows[0]||!(await bcrypt.compare(old,r.rows[0].password_hash||'')))return res.status(400).json({error:'كلمة المرور الحالية غير صحيحة.'});await query('UPDATE users SET password_hash=$1,must_change_password=false,updated_at=NOW() WHERE id=$2',[await bcrypt.hash(next,12),req.auth.id]);await audit(req,'password_changed','user',req.auth.id);res.json({ok:true,message:'تم تغيير كلمة المرور.'});});
app.patch('/api/me',auth,async(req,res)=>{const {name,email}=req.body;const r=await query('UPDATE users SET name=COALESCE($1,name),email=COALESCE($2,email),updated_at=NOW() WHERE id=$3 RETURNING id,name,email,phone,role,status',[name?String(name).trim():null,email?String(email).trim().toLowerCase():null,req.auth.id]);res.json({user:r.rows[0]});});
app.post('/api/provider/documents',auth,roles('provider'),upload.single('document'),async(req,res)=>{if(!req.file)return res.status(400).json({error:'اختر ملفًا أولًا.'});const type=String(req.body.documentType||'identity');const r=await query('INSERT INTO provider_documents(provider_id,document_type,file_path,original_name) VALUES($1,$2,$3,$4) RETURNING id,document_type,status,created_at',[req.auth.id,type,'/uploads/'+req.file.filename,req.file.originalname]);await audit(req,'provider_document_uploaded','document',r.rows[0].id,{type});res.status(201).json({document:r.rows[0],message:'تم رفع المستند وهو بانتظار مراجعة الإدارة.'});});
app.get('/api/provider/documents',auth,roles('provider'),async(req,res)=>{const r=await query('SELECT id,document_type,original_name,status,review_note,created_at FROM provider_documents WHERE provider_id=$1 ORDER BY created_at DESC',[req.auth.id]);res.json({documents:r.rows});});

