app.post('/api/complaints/:id/messages',auth,async(req,res)=>{if(!['customer','provider'].includes(req.auth.role))return res.status(403).json({error:'استخدم واجهة الإدارة للمراسلة الإدارية.'});const body=String(req.body.body||'').trim();if(!body||body.length>4000)return res.status(400).json({error:'اكتب رسالة من 1 إلى 4000 حرف.'});const r=await query('SELECT * FROM complaints WHERE id=$1',[req.params.id]);const c=r.rows[0];if(!c)return res.status(404).json({error:'الشكوى غير موجودة.'});if(c.status==='closed')return res.status(409).json({error:'الشكوى مغلقة ولا يمكن إضافة رسائل جديدة.'});if(req.auth.role==='customer'&&String(c.customer_id)!==String(req.auth.id))return res.status(403).json({error:'لا تملك صلاحية.'});if(req.auth.role==='provider'&&String(c.provider_id)!==String(req.auth.id))return res.status(403).json({error:'لا تملك صلاحية.'});const audience=req.auth.role==='customer'?'customer':'provider';const m=await query('INSERT INTO complaint_messages(complaint_id,sender_id,audience,body) VALUES($1,$2,$3,$4) RETURNING *',[c.id,req.auth.id,audience,body]);await query("UPDATE complaints SET status=CASE WHEN status='new' THEN 'under_review' ELSE status END,updated_at=NOW() WHERE id=$1",[c.id]);res.status(201).json({message:m.rows[0]});});
