// Provider operations
app.get('/api/provider/services',auth,roles('provider'),async(req,res)=>{const [all,chosen]=await Promise.all([query('SELECT id,name,category,description,needs_equipment,needs_qualification FROM services WHERE active=true ORDER BY name'),query('SELECT service_id,experience_note,equipment_note,approved FROM provider_services WHERE provider_id=$1',[req.auth.id])]);res.json({services:all.rows,chosen:chosen.rows});});
app.put('/api/provider/services',auth,roles('provider'),async(req,res)=>{const ids=Array.isArray(req.body.services)?req.body.services:[];await query('DELETE FROM provider_services WHERE provider_id=$1',[req.auth.id]);for(const x of ids){const sid=Number(x.serviceId);if(!Number.isInteger(sid))continue;await query('INSERT INTO provider_services(provider_id,service_id,experience_note,equipment_note,approved) SELECT $1,id,$3,$4,false FROM services WHERE id=$2 AND active=true ON CONFLICT DO NOTHING',[req.auth.id,sid,String(x.experienceNote||''),String(x.equipmentNote||'')]);}res.json({ok:true,message:'تم حفظ الخدمات. الخدمات التي تحتاج اعتمادًا إضافيًا ستظل بانتظار مراجعة الإدارة.'});});
app.patch('/api/provider/availability',auth,roles('provider'),async(req,res)=>{const value=req.body.availability;if(!['available','busy','offline'].includes(value))return res.status(400).json({error:'حالة التوافر غير صحيحة.'});const user=await query("SELECT status FROM users WHERE id=$1 AND role='provider'",[req.auth.id]);if(user.rows[0]?.status!=='active')return res.status(403).json({error:'يجب اعتماد حسابك أولًا.'});if(value==='offline'){const active=await query("SELECT id FROM orders WHERE assigned_provider_id=$1 AND status IN ('accepted','en_route','arrived','in_progress') LIMIT 1",[req.auth.id]);if(active.rows[0])return res.status(409).json({error:'لديك طلب نشط. أنهِ الطلب أو نسّق مع الإدارة قبل إيقاف التوافر.'});}await query('UPDATE provider_profiles SET availability=$1 WHERE user_id=$2',[value,req.auth.id]);res.json({ok:true,availability:value});});
app.post('/api/provider/location',auth,roles('provider'),async(req,res)=>{const {lat,lng,accuracy,speed,heading}=req.body;if(!Number.isFinite(Number(lat))||!Number.isFinite(Number(lng))||Math.abs(Number(lat))>90||Math.abs(Number(lng))>180)return res.status(400).json({error:'إحداثيات الموقع غير صحيحة.'});const active=await query("SELECT id FROM orders WHERE assigned_provider_id=$1 AND status IN ('assigned','accepted','en_route','arrived','in_progress') ORDER BY created_at DESC LIMIT 1",[req.auth.id]);const orderId=active.rows[0]?.id||null;await query('UPDATE provider_profiles SET current_lat=$1,current_lng=$2,location_accuracy=$3,location_updated_at=NOW() WHERE user_id=$4',[lat,lng,Number(accuracy)||null,req.auth.id]);if(orderId)await query('INSERT INTO location_history(provider_id,order_id,lat,lng,accuracy,speed,heading) VALUES($1,$2,$3,$4,$5,$6,$7)',[req.auth.id,orderId,lat,lng,Number(accuracy)||null,Number(speed)||null,Number(heading)||null]);if(orderId)io.to('order:'+orderId).emit('location:update',{providerId:req.auth.id,lat:Number(lat),lng:Number(lng),updatedAt:new Date().toISOString()});res.json({ok:true,orderId});});
app.get('/api/provider/orders',auth,roles('provider'),async(req,res)=>{const [offers,assigned]=await Promise.all([query(`SELECT d.*,o.order_code,o.service_name,o.vehicle_type,o.vehicle_make_model,o.issue_description,o.customer_lat,o.customer_lng,o.location_text,o.requested_at,o.status order_status,o.created_at order_created FROM dispatch_offers d JOIN orders o ON o.id=d.order_id WHERE d.provider_id=$1 AND d.status IN ('sent','accepted','rejected','expired') ORDER BY d.sent_at DESC LIMIT 100`,[req.auth.id]),query("SELECT o.*,u.name customer_name FROM orders o JOIN users u ON u.id=o.customer_id WHERE o.assigned_provider_id=$1 AND o.status NOT IN ('completed','cancelled','rejected') ORDER BY o.created_at DESC",[req.auth.id])]);res.json({offers:offers.rows,orders:assigned.rows});});
app.post('/api/provider/offers/:id/respond',auth,roles('provider'),async(req,res)=>{const decision=req.body.decision;if(!['accept','reject'].includes(decision))return res.status(400).json({error:'الرد غير صحيح.'});const r=await query("SELECT d.*,o.status order_status FROM dispatch_offers d JOIN orders o ON o.id=d.order_id WHERE d.id=$1 AND d.provider_id=$2 AND d.status='sent' AND d.expires_at>NOW()",[req.params.id,req.auth.id]);if(!r.rows[0])return res.status(409).json({error:'انتهت مهلة الطلب أو لم يعد متاحًا.'});const offer=r.rows[0];if(decision==='reject'){await query("UPDATE dispatch_offers SET status='rejected',responded_at=NOW(),response_note=$1 WHERE id=$2",[String(req.body.reason||'لم يحدد السبب'),offer.id]);await query('UPDATE provider_profiles SET rejected_count=rejected_count+1,response_seconds_avg=CASE WHEN response_seconds_avg=0 THEN EXTRACT(EPOCH FROM (NOW()-$1::timestamptz)) ELSE response_seconds_avg*0.8+EXTRACT(EPOCH FROM (NOW()-$1::timestamptz))*0.2 END WHERE user_id=$2',[offer.sent_at,req.auth.id]);await event(offer.order_id,req.auth.id,'provider_rejected',offer.order_status,offer.order_status,'رفض مقدم الخدمة الطلب');dispatchOrder(offer.order_id).catch(console.error);return res.json({ok:true,message:'تم رفض الطلب وإرساله إلى التالي.'});}
  const client=await pool.connect();try{await client.query('BEGIN');const lock=await client.query("SELECT * FROM orders WHERE id=$1 FOR UPDATE",[offer.order_id]);if(!lock.rows[0]||['completed','cancelled','assigned','accepted','en_route','arrived','in_progress'].includes(lock.rows[0].status))throw new Error('لم يعد الطلب متاحًا.');await client.query("UPDATE dispatch_offers SET status='expired' WHERE order_id=$1 AND status='sent' AND id<>$2",[offer.order_id,offer.id]);await client.query("UPDATE dispatch_offers SET status='accepted',responded_at=NOW() WHERE id=$1",[offer.id]);await client.query("UPDATE orders SET assigned_provider_id=$1,status='accepted',dispatch_status='assigned',estimated_minutes=$3,estimated_distance_km=$4,accepted_at=NOW(),updated_at=NOW() WHERE id=$2",[req.auth.id,offer.order_id,offer.estimated_minutes,offer.estimated_distance_km]);await client.query("UPDATE provider_profiles SET accepted_count=accepted_count+1,availability='busy',response_seconds_avg=CASE WHEN response_seconds_avg=0 THEN EXTRACT(EPOCH FROM (NOW()-$1::timestamptz)) ELSE response_seconds_avg*0.8+EXTRACT(EPOCH FROM (NOW()-$1::timestamptz))*0.2 END WHERE user_id=$2",[offer.sent_at,req.auth.id]);await client.query("INSERT INTO order_events(order_id,actor_id,event_type,from_status,to_status,note) VALUES($1,$2,'provider_accepted',$3,'accepted','قبل مقدم الخدمة الطلب')",[offer.order_id,req.auth.id,lock.rows[0].status]);await client.query('COMMIT');io.to('order:'+offer.order_id).emit('order:update',{orderId:offer.order_id,status:'accepted'});res.json({ok:true,message:'تم قبول الطلب.'});}catch(e){await client.query('ROLLBACK');res.status(409).json({error:e.message||'تعذر قبول الطلب.'});}finally{client.release();}});
app.post('/api/provider/orders/:id/quote',auth,roles('provider'),async(req,res)=>{const price=Number(req.body.price),note=String(req.body.note||'').trim();if(!Number.isFinite(price)||price<0)return res.status(400).json({error:'أدخل سعرًا صحيحًا غير سالب.'});const r=await query("SELECT * FROM orders WHERE id=$1 AND assigned_provider_id=$2 AND status IN ('accepted','en_route','arrived')",[req.params.id,req.auth.id]);const o=r.rows[0];if(!o)return res.status(404).json({error:'الطلب غير موجود أو لا يمكن تسعيره في حالته الحالية.'});if(o.quote_status==='pending')return res.status(409).json({error:'هناك عرض سعر بانتظار رد العميل بالفعل.'});const subtotal=await query('SELECT COALESCE(SUM(quantity*unit_price),0)::numeric total FROM order_items WHERE order_id=$1',[o.id]);if(price<Number(subtotal.rows[0].total||0))return res.status(400).json({error:'عرض السعر لا يمكن أن يكون أقل من إجمالي المنتجات الموجودة في الطلب.'});await query("UPDATE orders SET price_quote=$1,quote_note=$2,quote_status='pending',quote_sent_at=NOW(),updated_at=NOW() WHERE id=$3",[price,note,o.id]);await event(o.id,req.auth.id,'quote_sent',o.status,o.status,'أرسل مقدم الخدمة عرض سعر',{price,note});io.to('order:'+o.id).emit('order:update',{orderId:o.id,quoteStatus:'pending'});res.json({ok:true,message:'تم إرسال عرض السعر إلى العميل.'});});
app.post('/api/orders/:id/quote-response',auth,roles('customer'),async(req,res)=>{const decision=req.body.decision;if(!['accept','reject'].includes(decision))return res.status(400).json({error:'القرار غير صحيح.'});const r=await query("SELECT * FROM orders WHERE id=$1 AND customer_id=$2 AND quote_status='pending' AND status IN ('accepted','en_route','arrived')",[req.params.id,req.auth.id]);const o=r.rows[0];if(!o)return res.status(409).json({error:'لا يوجد عرض سعر بانتظار موافقتك.'});const status=decision==='accept'?'accepted':'rejected';await query('UPDATE orders SET quote_status=$1,final_price=CASE WHEN $1=\'accepted\' THEN price_quote ELSE final_price END,updated_at=NOW() WHERE id=$2',[status,o.id]);await event(o.id,req.auth.id,decision==='accept'?'quote_accepted':'quote_rejected',o.status,o.status,decision==='accept'?'وافق العميل على السعر':'رفض العميل عرض السعر');io.to('order:'+o.id).emit('order:update',{orderId:o.id,quoteStatus:status});res.json({ok:true,quoteStatus:status,message:decision==='accept'?'تمت الموافقة على السعر.':'تم رفض عرض السعر؛ يمكن لمقدم الخدمة إرسال عرض معدل.'});});
app.patch('/api/provider/orders/:id/status',auth,roles('provider'),async(req,res)=>{const allowed={en_route:['accepted'],'arrived':['en_route'],'in_progress':['arrived'],'completed':['in_progress']};const next=req.body.status;if(!allowed[next])return res.status(400).json({error:'حالة الطلب غير صحيحة.'});const r=await query('SELECT * FROM orders WHERE id=$1 AND assigned_provider_id=$2',[req.params.id,req.auth.id]);const o=r.rows[0];if(!o)return res.status(404).json({error:'الطلب غير موجود.'});if(!allowed[next].includes(o.status))return res.status(409).json({error:'لا يمكن الانتقال إلى هذه الحالة من الحالة الحالية.'});if(next==='in_progress'&&['not_sent','pending','rejected'].includes(o.quote_status))return res.status(409).json({error:'يجب إرسال عرض السعر وانتظار موافقة العميل قبل بدء الخدمة.'});const col={en_route:'en_route_at',arrived:'arrived_at',in_progress:'started_at',completed:'completed_at'}[next];if(next==='completed'){const finalPrice=req.body.finalPrice===undefined||req.body.finalPrice===null||req.body.finalPrice===''?null:Number(req.body.finalPrice);if(finalPrice!==null&&(!Number.isFinite(finalPrice)||finalPrice<0))return res.status(400).json({error:'السعر النهائي غير صحيح.'});if(finalPrice!==null){const subtotal=await query('SELECT COALESCE(SUM(quantity*unit_price),0)::numeric total FROM order_items WHERE order_id=$1',[o.id]);if(finalPrice<Number(subtotal.rows[0].total||0))return res.status(400).json({error:'السعر النهائي لا يمكن أن يكون أقل من إجمالي المنتجات المسجلة.'});}await query(`UPDATE orders SET status=$1,${col}=NOW(),final_price=COALESCE($3,final_price,price_quote),updated_at=NOW() WHERE id=$2`,[next,o.id,finalPrice]);}else{await query(`UPDATE orders SET status=$1,${col}=NOW(),updated_at=NOW() WHERE id=$2`,[next,o.id]);}await event(o.id,req.auth.id,'provider_status_changed',o.status,next);if(next==='completed'){await query("UPDATE provider_profiles SET completed_count=completed_count+1,availability='available' WHERE user_id=$1",[req.auth.id]);await query('UPDATE orders SET stock_reserved=false,stock_committed=true WHERE id=$1',[o.id]);}io.to('order:'+o.id).emit('order:update',{orderId:o.id,status:next});res.json({ok:true,status:next});});

// Admin: all dashboard controls
app.get('/api/admin/overview',auth,roles('admin'),async(req,res)=>{const [counts,providers,complaints,services,areas,rejections,offerStats,stock]=await Promise.all([
 query(`SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE status IN ('new','dispatching'))::int pending,COUNT(*) FILTER(WHERE status IN ('assigned','accepted','en_route','arrived','in_progress'))::int active,COUNT(*) FILTER(WHERE status='completed')::int completed,COUNT(*) FILTER(WHERE status='cancelled')::int cancelled,COUNT(*) FILTER(WHERE status='rejected')::int rejected,COUNT(*) FILTER(WHERE created_at>=CURRENT_DATE)::int today FROM orders`),
 query(`SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE u.status='pending')::int pending,COUNT(*) FILTER(WHERE u.status='active')::int approved,COUNT(*) FILTER(WHERE pp.availability='available')::int available,COUNT(*) FILTER(WHERE pp.availability='busy')::int busy,COALESCE(AVG(pp.rating_avg),0)::numeric(4,2) rating FROM users u LEFT JOIN provider_profiles pp ON pp.user_id=u.id WHERE u.role='provider'`),
 query("SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE status IN ('new','under_review','waiting_customer','waiting_provider','investigating'))::int open FROM complaints"),
 query('SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE active)::int active FROM services'),
 query(`SELECT COALESCE(NULLIF(o.location_text,''),CASE WHEN o.customer_lat IS NOT NULL AND o.customer_lng IS NOT NULL THEN CONCAT(ROUND(o.customer_lat::numeric,2),', ',ROUND(o.customer_lng::numeric,2)) ELSE 'موقع غير موصوف' END) area,COUNT(DISTINCT o.id)::int orders,COUNT(DISTINCT o.id) FILTER(WHERE o.status='completed')::int completed,COUNT(DISTINCT o.id) FILTER(WHERE o.status='cancelled')::int cancelled,COUNT(d.id) FILTER(WHERE d.status='rejected')::int rejected_offers,COUNT(d.id) FILTER(WHERE d.status='expired')::int timed_out_offers FROM orders o LEFT JOIN dispatch_offers d ON d.order_id=o.id WHERE o.created_at>NOW()-INTERVAL '30 days' GROUP BY area ORDER BY orders DESC LIMIT 12`),
 query(`SELECT COALESCE(d.response_note,'لم يحدد السبب') reason,COUNT(*)::int count FROM dispatch_offers d WHERE d.status='rejected' AND d.sent_at>NOW()-INTERVAL '30 days' GROUP BY reason ORDER BY count DESC LIMIT 8`),
 query(`SELECT COUNT(*)::int sent,COUNT(*) FILTER(WHERE status='accepted')::int accepted,COUNT(*) FILTER(WHERE status='rejected')::int rejected,COUNT(*) FILTER(WHERE status='expired')::int expired FROM dispatch_offers WHERE sent_at>NOW()-INTERVAL '30 days'`),
 query(`SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE stock_qty<=low_stock_threshold)::int low_stock FROM products WHERE active=true`)
]);const t=counts.rows[0],p=providers.rows[0],os=offerStats.rows[0];res.json({orders:t,providers:p,complaints:complaints.rows[0],services:services.rows[0],stock:stock.rows[0],areas:areas.rows,rejectionReasons:rejections.rows,offerStats:os,completionRate:t.total?Math.round(t.completed/t.total*1000)/10:0,acceptanceRate:os.sent?Math.round(os.accepted/os.sent*1000)/10:0,rejectionRate:os.sent?Math.round(os.rejected/os.sent*1000)/10:0,timeoutRate:os.sent?Math.round(os.expired/os.sent*1000)/10:0});});
app.get('/api/admin/orders',auth,roles('admin'),async(req,res)=>{const status=req.query.status;const params=[];let where='';if(status){params.push(status);where='WHERE o.status=$1';}const r=await query(`SELECT o.*,cu.name customer_name,cu.phone customer_phone,p.name provider_name,pp.current_lat provider_lat,pp.current_lng provider_lng,pp.location_updated_at provider_location_updated_at FROM orders o JOIN users cu ON cu.id=o.customer_id LEFT JOIN users p ON p.id=o.assigned_provider_id LEFT JOIN provider_profiles pp ON pp.user_id=o.assigned_provider_id ${where} ORDER BY o.created_at DESC LIMIT 500`,params);res.json({orders:r.rows});});
app.get('/api/admin/providers',auth,roles('admin'),async(req,res)=>{const r=await query(`SELECT u.id,u.name,u.phone,u.email,u.status,u.created_at,pp.business_name,pp.vehicle_type,pp.vehicle_plate,pp.availability,pp.current_lat,pp.current_lng,pp.location_accuracy,pp.location_updated_at,pp.rating_avg,pp.rating_count,pp.completed_count,pp.accepted_count,pp.rejected_count,pp.timeout_count,pp.response_seconds_avg,pp.service_radius_km,pp.branch_id,b.name branch_name,(SELECT COUNT(*)::int FROM provider_documents d WHERE d.provider_id=u.id) document_count FROM users u JOIN provider_profiles pp ON pp.user_id=u.id LEFT JOIN branches b ON b.id=pp.branch_id WHERE u.role='provider' ORDER BY u.created_at DESC`);res.json({providers:r.rows});});
app.get('/api/admin/providers/:id(\\d+)',auth,roles('admin'),async(req,res)=>{const [u,d,s]=await Promise.all([query('SELECT u.id,u.name,u.phone,u.email,u.status,u.created_at,pp.* FROM users u JOIN provider_profiles pp ON pp.user_id=u.id WHERE u.id=$1 AND u.role=\'provider\'',[req.params.id]),query('SELECT id,document_type,file_path,original_name,status,review_note,created_at FROM provider_documents WHERE provider_id=$1 ORDER BY created_at DESC',[req.params.id]),query('SELECT ps.*,s.name service_name FROM provider_services ps JOIN services s ON s.id=ps.service_id WHERE ps.provider_id=$1',[req.params.id])]);if(!u.rows[0])return res.status(404).json({error:'مقدم الخدمة غير موجود.'});res.json({provider:u.rows[0],documents:d.rows,services:s.rows});});
app.patch('/api/admin/providers/:id/branch',auth,roles('admin'),async(req,res)=>{const branchId=req.body.branchId===null||req.body.branchId===''?null:Number(req.body.branchId);if(branchId!==null){const b=await query('SELECT id FROM branches WHERE id=$1 AND active=true',[branchId]);if(!b.rows[0])return res.status(400).json({error:'الفرع غير موجود أو غير مفعّل.'});}const r=await query('UPDATE provider_profiles SET branch_id=$1 WHERE user_id=$2 RETURNING branch_id',[branchId,req.params.id]);if(!r.rows[0])return res.status(404).json({error:'مقدم الخدمة غير موجود.'});await audit(req,'provider_branch_assigned','provider',req.params.id,{branchId});res.json({branchId:r.rows[0].branch_id});});
app.patch('/api/admin/providers/:id/review',auth,roles('admin'),async(req,res)=>{const status=req.body.status;if(!['active','rejected','suspended','pending'].includes(status))return res.status(400).json({error:'الحالة غير صحيحة.'});if(status==='active'){const docs=await query("SELECT COUNT(*) FILTER(WHERE document_type='identity' AND status='approved')::int identity_ok,COUNT(*) FILTER(WHERE document_type='portrait' AND status='approved')::int portrait_ok FROM provider_documents WHERE provider_id=$1",[req.params.id]);if(!docs.rows[0]||docs.rows[0].identity_ok<1||docs.rows[0].portrait_ok<1)return res.status(400).json({error:'لا يمكن اعتماد مقدم الخدمة قبل اعتماد وثيقة الهوية والصورة الشخصية من الإدارة.'});}const r=await query("UPDATE users SET status=$1,updated_at=NOW() WHERE id=$2 AND role='provider' RETURNING id,status",[status,req.params.id]);if(!r.rows[0])return res.status(404).json({error:'مقدم الخدمة غير موجود.'});await query('UPDATE provider_profiles SET approved_at=CASE WHEN $1=\'active\' THEN NOW() ELSE approved_at END,approved_by=$2,rejection_reason=$3 WHERE user_id=$4',[status,req.auth.id,req.body.reason||'',req.params.id]);await audit(req,'provider_reviewed','provider',req.params.id,{status,reason:req.body.reason||''});res.json({provider:r.rows[0]});});
app.get('/api/admin/documents/:id/file',auth,roles('admin'),async(req,res)=>{const r=await query('SELECT file_path,original_name FROM provider_documents WHERE id=$1',[req.params.id]);if(!r.rows[0])return res.status(404).json({error:'المستند غير موجود.'});const file=path.join(__dirname,r.rows[0].file_path.replace(/^\//,''));if(!file.startsWith(uploadsDir+path.sep)||!fs.existsSync(file))return res.status(404).json({error:'ملف المستند غير متاح.'});res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('Content-Disposition',`inline; filename*=UTF-8''${encodeURIComponent(r.rows[0].original_name)}`);res.sendFile(file);});
app.patch('/api/admin/documents/:id/review',auth,roles('admin'),async(req,res)=>{const status=req.body.status;if(!['approved','rejected','pending'].includes(status))return res.status(400).json({error:'الحالة غير صحيحة.'});const r=await query('UPDATE provider_documents SET status=$1,review_note=$2,reviewed_by=$3 WHERE id=$4 RETURNING *',[status,String(req.body.note||''),req.auth.id,req.params.id]);if(!r.rows[0])return res.status(404).json({error:'المستند غير موجود.'});res.json({document:{id:r.rows[0].id,status:r.rows[0].status}});});
app.patch('/api/admin/providers/:id/services/:serviceId',auth,roles('admin'),async(req,res)=>{const approved=!!req.body.approved;const r=await query('UPDATE provider_services SET approved=$1 WHERE provider_id=$2 AND service_id=$3 RETURNING *',[approved,req.params.id,req.params.serviceId]);if(!r.rows[0])return res.status(404).json({error:'الخدمة المحددة غير موجودة ضمن خدمات مقدم الخدمة.'});await audit(req,'provider_service_reviewed','provider_service',`${req.params.id}:${req.params.serviceId}`,{approved});res.json({service:r.rows[0]});});
app.get('/api/admin/orders/:id/locations',auth,roles('admin'),async(req,res)=>{const o=await query('SELECT id,order_code FROM orders WHERE id=$1',[req.params.id]);if(!o.rows[0])return res.status(404).json({error:'الطلب غير موجود.'});const r=await query('SELECT lat,lng,accuracy,recorded_at,speed,heading FROM location_history WHERE order_id=$1 ORDER BY recorded_at',[req.params.id]);res.json({order:o.rows[0],points:r.rows});});
app.get('/api/admin/providers-map',auth,roles('admin'),async(req,res)=>{const r=await query(`SELECT u.id,u.name,pp.availability,pp.current_lat lat,pp.current_lng lng,pp.location_accuracy,pp.location_updated_at,pp.rating_avg,o.id order_id,o.order_code,o.status order_status,o.customer_lat,o.customer_lng,o.location_text FROM users u JOIN provider_profiles pp ON pp.user_id=u.id LEFT JOIN LATERAL (SELECT * FROM orders WHERE assigned_provider_id=u.id AND status IN ('accepted','en_route','arrived','in_progress') ORDER BY created_at DESC LIMIT 1) o ON true WHERE u.role='provider' AND u.status='active'`);res.json({providers:r.rows});});
