app.put('/api/admin/settings/:key',auth,roles('admin'),async(req,res)=>{const allowed=['dispatch','business','privacy'];if(!allowed.includes(req.params.key))return res.status(400).json({error:'هذا الإعداد غير قابل للتعديل من هذه الواجهة.'});let value=req.body.value&&typeof req.body.value==='object'&&!Array.isArray(req.body.value)?req.body.value:{};if(req.params.key==='business'){const old=await query("SELECT value FROM settings WHERE key='business'");value={...(old.rows[0]?.value||{}),...value};if(!String(value.name||'').trim()||String(value.name).length>100)return res.status(400).json({error:'اسم النشاط مطلوب وبحد أقصى 100 حرف.'});if(value.logoUrl&&!(/^https?:\/\//i.test(String(value.logoUrl))||String(value.logoUrl).startsWith('/api/brand-assets/logo-')))return res.status(400).json({error:'رابط الشعار يجب أن يكون HTTP/HTTPS أو صورة مرفوعة داخل التطبيق.'});for(const k of ['primaryColor','secondaryColor'])if(value[k]&&!/^#[0-9a-f]{6}$/i.test(String(value[k])))return res.status(400).json({error:'ألوان الهوية يجب أن تكون بصيغة HEX مثل #176b58.'});if(value.currency&&!/^[A-Z]{3}$/.test(String(value.currency)))return res.status(400).json({error:'رمز العملة غير صحيح.'});if(value.contactEmail&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value.contactEmail)))return res.status(400).json({error:'بريد التواصل غير صحيح.'});}await query('INSERT INTO settings(key,value,updated_by,updated_at) VALUES($1,$2,$3,NOW()) ON CONFLICT(key) DO UPDATE SET value=$2,updated_by=$3,updated_at=NOW()',[req.params.key,JSON.stringify(value),req.auth.id]);await audit(req,'setting_updated','setting',req.params.key);res.json({ok:true});});
function safeWebUrl(value){const v=String(value||'').trim();if(!v)return '';try{const u=new URL(v, 'https://placeholder.invalid');return ['http:','https:'].includes(u.protocol)?v:'';}catch{return '';}}
