app.get('/api/admin/reports',auth,roles('admin'),async(req,res)=>{const [daily,service,ratings,offers,finance]=await Promise.all([
 query(`SELECT DATE(created_at) day,COUNT(*)::int orders,COUNT(*) FILTER(WHERE status='completed')::int completed FROM orders WHERE created_at>NOW()-INTERVAL '30 days' GROUP BY DATE(created_at) ORDER BY day`),
 query(`SELECT service_name,COUNT(*)::int orders,COUNT(*) FILTER(WHERE status='completed')::int completed FROM orders WHERE created_at>NOW()-INTERVAL '90 days' GROUP BY service_name ORDER BY orders DESC LIMIT 20`),
 query('SELECT score,COUNT(*)::int count FROM ratings GROUP BY score ORDER BY score'),
 query(`SELECT COUNT(*)::int sent,COUNT(*) FILTER(WHERE status='accepted')::int accepted,COUNT(*) FILTER(WHERE status='rejected')::int rejected,COUNT(*) FILTER(WHERE status='expired')::int expired FROM dispatch_offers WHERE sent_at>NOW()-INTERVAL '30 days'`),
 query(`SELECT (SELECT COALESCE(SUM(COALESCE(final_price,price_quote,0)),0)::numeric FROM orders WHERE status='completed' AND created_at>NOW()-INTERVAL '90 days') revenue,(SELECT COUNT(*)::int FROM orders WHERE status='completed' AND created_at>NOW()-INTERVAL '90 days') completed_orders,(SELECT COALESCE(SUM(oi.quantity*oi.unit_price),0)::numeric FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.status='completed' AND o.created_at>NOW()-INTERVAL '90 days') product_sales,(SELECT COALESCE(SUM(oi.quantity*oi.unit_cost),0)::numeric FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.status='completed' AND o.created_at>NOW()-INTERVAL '90 days') product_cost`)
]);res.json({daily:daily.rows,services:service.rows,ratings:ratings.rows,offers:offers.rows[0],finance:finance.rows[0]});});

// Automatic sequential dispatch: hard eligibility checks first, then score by ETA/reliability.
function haversineKm(a,b,c,d){const R=6371,rad=x=>x*Math.PI/180;const x=rad(c-a),y=rad(d-b);return 2*R*Math.asin(Math.sqrt(Math.sin(x/2)**2+Math.cos(rad(a))*Math.cos(rad(c))*Math.sin(y/2)**2));}
async function estimateRoute(providerLat,providerLng,customerLat,customerLng,overview=false){if([providerLat,providerLng,customerLat,customerLng].some(x=>x==null))return null;const base=(process.env.ROUTING_BASE_URL||'https://router.project-osrm.org').replace(/\/$/,'');try{const url=`${base}/route/v1/driving/${providerLng},${providerLat};${customerLng},${customerLat}?overview=${overview?'full':'false'}&geometries=geojson`;const ctl=new AbortController();const timer=setTimeout(()=>ctl.abort(),3500);const r=await fetch(url,{signal:ctl.signal});clearTimeout(timer);if(!r.ok)return null;const j=await r.json();if(j.code!=='Ok'||!j.routes?.[0])return null;return {minutes:Math.round(j.routes[0].duration/60),distanceKm:Math.round(j.routes[0].distance/100)/10,geometry:j.routes[0].geometry||null};}catch{return null;}}
app.get('/api/route',rateLimit({windowMs:60000,limit:60,standardHeaders:true,legacyHeaders:false}),async(req,res)=>{const {fromLat,fromLng,toLat,toLng}=req.query;const vals=[fromLat,fromLng,toLat,toLng].map(Number);if(vals.some(x=>!Number.isFinite(x))||Math.abs(vals[0])>90||Math.abs(vals[2])>90||Math.abs(vals[1])>180||Math.abs(vals[3])>180)return res.status(400).json({error:'إحداثيات المسار غير صحيحة.'});const route=await estimateRoute(vals[0],vals[1],vals[2],vals[3],true);if(route)return res.json({source:'road-routing',...route});const distance=haversineKm(vals[0],vals[1],vals[2],vals[3])*1.35;res.json({source:'approximate',minutes:Math.round(distance*2.4+5),distanceKm:Math.round(distance*10)/10,geometry:null,note:'تعذر حساب مسار الطرق؛ المسافة تقديرية وليست مسافة قيادة مؤكدة.'});});
async function releaseReservedStock(orderId){const client=await pool.connect();try{await client.query('BEGIN');const o=await client.query('SELECT stock_reserved FROM orders WHERE id=$1 FOR UPDATE',[orderId]);if(!o.rows[0]?.stock_reserved){await client.query('COMMIT');return;}const items=await client.query('SELECT product_id,quantity FROM order_items WHERE order_id=$1 AND product_id IS NOT NULL',[orderId]);for(const i of items.rows)await client.query('UPDATE products SET stock_qty=stock_qty+$1,updated_at=NOW() WHERE id=$2',[i.quantity,i.product_id]);await client.query('UPDATE orders SET stock_reserved=false WHERE id=$1',[orderId]);await client.query('COMMIT');}catch(e){await client.query('ROLLBACK');throw e;}finally{client.release();}}
async function dispatchOrder(orderId){const setting=await query("SELECT value FROM settings WHERE key='dispatch'");const cfg=setting.rows[0]?.value||{responseTimeoutSeconds:60,weights:{eta:35,rating:25,completion:20,response:10,readiness:10}};const oR=await query('SELECT * FROM orders WHERE id=$1',[orderId]);const o=oR.rows[0];if(!o||!['new','dispatching'].includes(o.status))return;
 const existing=await query("SELECT COUNT(*)::int n FROM dispatch_offers WHERE order_id=$1 AND status='sent' AND expires_at>NOW()",[orderId]);if(existing.rows[0].n>0)return;
 const serv=o.service_id?await query('SELECT * FROM services WHERE id=$1',[o.service_id]):{rows:[]};const s=serv.rows[0];
 const candidates=await query(`SELECT u.id,u.name,pp.current_lat,pp.current_lng,pp.location_updated_at,pp.service_radius_km,pp.rating_avg,pp.rating_count,pp.completed_count,pp.accepted_count,pp.rejected_count,pp.timeout_count,pp.response_seconds_avg,pp.availability FROM users u JOIN provider_profiles pp ON pp.user_id=u.id JOIN provider_services ps ON ps.provider_id=u.id JOIN services sv ON sv.id=ps.service_id WHERE u.role='provider' AND u.status='active' AND pp.availability='available' AND ps.approved=true AND sv.active=true AND ($1::bigint IS NULL OR sv.id=$1) AND ($2::text <> 'shop' OR pp.branch_id=$3) AND NOT EXISTS(SELECT 1 FROM orders x WHERE x.assigned_provider_id=u.id AND x.status IN ('accepted','en_route','arrived','in_progress')) ORDER BY pp.rating_avg DESC`,[o.service_id,o.service_mode,o.branch_id]);
 const eligible=[];for(const p of candidates.rows){if(o.service_mode==='mobile'&&(p.current_lat==null||p.current_lng==null||!p.location_updated_at||(Date.now()-new Date(p.location_updated_at).getTime()>180000)))continue;if(o.customer_lat!=null&&o.customer_lng!=null&&p.current_lat!=null&&p.current_lng!=null){const straight=haversineKm(Number(p.current_lat),Number(p.current_lng),Number(o.customer_lat),Number(o.customer_lng));if(straight>Math.min(Number(p.service_radius_km||35),Number(cfg.maxProviderRadiusKm||50)))continue;}
 let route=await estimateRoute(p.current_lat,p.current_lng,o.customer_lat,o.customer_lng);let eta=route?.minutes??null;let distanceKm=route?.distanceKm??null;if(eta==null&&p.current_lat!=null&&p.current_lng!=null&&o.customer_lat!=null&&o.customer_lng!=null){distanceKm=Math.round(haversineKm(Number(p.current_lat),Number(p.current_lng),Number(o.customer_lat),Number(o.customer_lng))*1.35*10)/10;eta=Math.round(distanceKm*2.4+5);}if(eta==null)eta=999;
 const w=cfg.weights||{eta:35,rating:25,completion:20,response:10,readiness:10};const etaScore=Math.max(0,100-Math.min(100,eta));const ratingScore=p.rating_count?Number(p.rating_avg)/5*100:55;const compScore=Number(p.accepted_count)>0?Math.min(100,Number(p.completed_count)/Number(p.accepted_count)*100):60;const responseScore=p.response_seconds_avg?Math.max(0,100-Number(p.response_seconds_avg)/3):60;const weightTotal=Math.max(1,Number(w.eta??35)+Number(w.rating??25)+Number(w.completion??20)+Number(w.response??10)+Number(w.readiness??10));const score=(etaScore*Number(w.eta??35)+ratingScore*Number(w.rating??25)+compScore*Number(w.completion??20)+responseScore*Number(w.response??10)+100*Number(w.readiness??10))/weightTotal;eligible.push({...p,eta,distanceKm,score});}
 eligible.sort((a,b)=>a.score-b.score?b.score-a.score:a.eta-b.eta); // score descending
 const used=await query('SELECT provider_id FROM dispatch_offers WHERE order_id=$1',[orderId]);const usedIds=new Set(used.rows.map(x=>String(x.provider_id)));const orderAge=Date.now()-new Date(o.service_mode==='shop'&&o.requested_at?o.requested_at:o.created_at).getTime();const dispatchWindowMs=o.service_mode==='shop'?30*60*1000:10*60*1000;
 if(!eligible.length){if(orderAge>=dispatchWindowMs){await query("UPDATE orders SET status='no_provider',dispatch_status='exhausted',updated_at=NOW() WHERE id=$1 AND status IN ('new','dispatching')",[orderId]);await event(orderId,null,'dispatch_exhausted','dispatching','no_provider','انتهت مهلة البحث دون توفر مقدم خدمة مؤهل');io.to('order:'+orderId).emit('order:update',{orderId,status:'no_provider'});await releaseReservedStock(orderId);}else{await query("UPDATE orders SET status='dispatching',dispatch_status='waiting_for_provider',updated_at=NOW() WHERE id=$1 AND status IN ('new','dispatching')",[orderId]);}return;}
 const next=eligible.find(p=>!usedIds.has(String(p.id)));if(!next){if(orderAge>=dispatchWindowMs){await query("UPDATE orders SET status='no_provider',dispatch_status='exhausted',updated_at=NOW() WHERE id=$1 AND status IN ('new','dispatching')",[orderId]);await event(orderId,null,'dispatch_exhausted','dispatching','no_provider','انتهت مهلة البحث بعد تجربة مقدمي الخدمة المتاحين');io.to('order:'+orderId).emit('order:update',{orderId,status:'no_provider'});await releaseReservedStock(orderId);}else{await query("UPDATE orders SET status='dispatching',dispatch_status='waiting_for_provider',updated_at=NOW() WHERE id=$1 AND status IN ('new','dispatching')",[orderId]);}return;}
 const timeout=Math.max(15,Math.min(600,Number(cfg.responseTimeoutSeconds)||60));const position=used.rows.length+1;const r=await query("INSERT INTO dispatch_offers(order_id,provider_id,rank_position,score,estimated_minutes,estimated_distance_km,status,expires_at) VALUES($1,$2,$3,$4,$5,$6,'sent',NOW()+(($7::text || ' seconds')::interval)) RETURNING *",[orderId,next.id,position,next.score,next.eta,next.distanceKm,timeout]);await query("UPDATE orders SET status='dispatching',dispatch_status='offering',updated_at=NOW() WHERE id=$1 AND status IN ('new','dispatching')",[orderId]);await event(orderId,null,'offer_sent','dispatching','dispatching',`إرسال العرض إلى مقدم الخدمة رقم ${next.id}`,{providerId:String(next.id),rank:position,etaMinutes:next.eta,distanceKm:next.distanceKm,timeoutSeconds:timeout});io.to('provider:'+next.id).emit('offer:new',{offer:r.rows[0],orderId,orderCode:o.order_code,serviceName:o.service_name,etaMinutes:next.eta,distanceKm:next.distanceKm,expiresAt:r.rows[0].expires_at});
}
async function dispatchMaintenance(){try{const expired=await query("UPDATE dispatch_offers SET status='expired',responded_at=NOW(),response_note='انتهت المهلة' WHERE status='sent' AND expires_at<=NOW() RETURNING order_id,provider_id");for(const e of expired.rows){await query('UPDATE provider_profiles SET timeout_count=timeout_count+1 WHERE user_id=$1',[e.provider_id]);await event(e.order_id,null,'offer_timed_out','dispatching','dispatching','انتهت مهلة الاستجابة',{providerId:String(e.provider_id)});dispatchOrder(e.order_id).catch(console.error);}const pending=await query("SELECT id FROM orders WHERE status IN ('new','dispatching') AND NOT EXISTS(SELECT 1 FROM dispatch_offers d WHERE d.order_id=orders.id AND d.status='sent' AND d.expires_at>NOW()) ORDER BY created_at LIMIT 50");for(const o of pending.rows)dispatchOrder(o.id).catch(console.error);}catch(e){console.error('dispatch maintenance:',e.message);}}

// Socket rooms are authorized against database ownership.
io.use(async(socket,next)=>{try{const raw=socket.handshake.auth?.token;if(!raw)return next(new Error('unauthorized'));socket.user=jwt.verify(raw,JWT_SECRET,{issuer:'darbak'});next();}catch{next(new Error('unauthorized'));}});
io.on('connection',socket=>{socket.on('join-order',async id=>{try{const r=await query('SELECT * FROM orders WHERE id=$1',[id]);const o=r.rows[0];if(!o)return;if(socket.user.role==='admin'||(socket.user.role==='customer'&&String(o.customer_id)===String(socket.user.id))||(socket.user.role==='provider'&&String(o.assigned_provider_id)===String(socket.user.id)))socket.join('order:'+id);}catch{}});socket.on('join-provider',()=>{if(socket.user.role==='provider')socket.join('provider:'+socket.user.id);});});

app.use((err,req,res,next)=>{console.error(err.stack||err);if(res.headersSent)return next(err);if(err instanceof multer.MulterError)return res.status(400).json({error:err.code==='LIMIT_FILE_SIZE'?'حجم الملف أكبر من الحد المسموح.':'تعذر رفع الملف.'});if(/^(يسمح بملفات|الشعار يجب أن يكون)/.test(String(err.message||'')))return res.status(400).json({error:err.message});res.status(500).json({error:process.env.NODE_ENV==='production'?'حدث خطأ داخلي. تحقق من سجل الخادم.':err.message||'حدث خطأ داخلي.'});});

initialize().then(()=>{server.listen(PORT,'0.0.0.0',()=>console.log(`البنشر الذكي running on port ${PORT}`));setInterval(dispatchMaintenance,5000);}).catch(e=>{console.error('Startup failed:',e);process.exit(1);});
